import { useCallback, useEffect, useState } from 'react';
import { useHasPermission } from '../hooks/usePermission';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import type { GroupedPermissions, PermissionItem } from '../types/roles.types';

const PermissionsCatalogPage = () => {
    const can = useHasPermission('list_permission');
    const [groups, setGroups] = useState<GroupedPermissions>({});
    const [loading, setLoading] = useState(true);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const res = await apiGet<{ data: GroupedPermissions }>({ endpoint: endpoints.accessControl.permissionList });
            const raw = res.data?.data;
            setGroups(raw && typeof raw === 'object' ? raw : {});
        } catch {
            setGroups({});
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        if (can) {
            load();
        }
    }, [load, can]);

    if (!can) {
        return <p className="mt-8 px-2 text-sm text-white-blue-700">ليس لديك صلاحية عرض قائمة الصلاحيات.</p>;
    }

    return (
        <div className="mt-6 w-full px-2">
            <UnderlineHeading text="قائمة الصلاحيات" />
            {loading ? (
                <p className="mt-6 text-sm text-white-blue-700">جاري التحميل…</p>
            ) : (
                <div className="mt-6 space-y-8">
                    {Object.entries(groups).map(([groub, items]) => (
                        <section key={groub} className="rounded-lg border border-[#E8E7EA] p-4 shadow-sm">
                            <h3 className="text-base font-semibold text-primery-blue-500 mb-3">{groub}</h3>
                            <ul className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
                                {(items as PermissionItem[]).map((p) => (
                                    <li key={p.id} className="text-sm text-white-blue-800 font-mono bg-white-blue-50 px-2 py-1 rounded">
                                        {p.name}
                                    </li>
                                ))}
                            </ul>
                        </section>
                    ))}
                </div>
            )}
        </div>
    );
};

export default PermissionsCatalogPage;
